// Busca dados SANITIZADOS da negociacao (sem contatos privados)
const crypto = require('crypto');
const d = $json.data;
const ts = String(Math.floor(Date.now()/1000));
const nonce = crypto.randomUUID();
const sig = crypto.createHmac('sha256', $env.BACKEND_WEBHOOK_SECRET).update(ts + '.' + nonce + '.').digest('hex');
return { json: { url: $env.BACKEND_BASE_URL + '/api/n8n/negociacoes/' + d.negotiation_id + '?provider_id=' + d.provider_id, ts, nonce, sig, data: d } };

// Monta a mensagem oficial com botoes ACEITAR / CONTRAPROPOSTA / RECUSAR
const n = $json;
const valor = (n.proposals.at(-1).amount_cents / 100).toFixed(2).replace('.', ',');
const texto = `Nova solicitacao na AirFlow
Servico: ${n.service}
Regiao: ${n.location.neighborhood}, ${n.location.city}
Valor proposto: R$ ${valor}
Prazo desejado: ${n.desired_date || 'a combinar'}

Responda:
1 ACEITAR
2 CONTRAPROPOSTA <valor>
3 RECUSAR`;
return { json: { texto, negotiation_id: n.negotiation_id } };
